Object.assign(catalogs.tr,{"Text orientation": "Metin yönü", "Automatic — all directions": "Otomatik — tüm yönler", "As captured": "Çekildiği gibi", "Rotate 90° clockwise": "Saat yönünde 90° döndür", "Rotate 180°": "180° döndür", "Rotate 90° counterclockwise": "Saat yönünün tersine 90° döndür", "Processing progress": "İşlem ilerlemesi"});

Object.assign(catalogs.fr,{"Automatically detect language(s)": "Détecter automatiquement les langues", "Text type": "Type de texte", "Printed text": "Texte imprimé", "Handwriting — experimental": "Écriture manuscrite — expérimentale", "Printed and handwritten — experimental": "Imprimé et manuscrit — expérimental", "Languages used: {languages}": "Langues utilisées : {languages}", "Estimated detection: review languages and select them manually if needed": "Détection approximative : vérifiez les langues et sélectionnez-les si nécessaire", "Automatic detection is approximate and supports up to three languages per page. Select languages manually for short or unclear text.": "La détection automatique est approximative et prend en charge trois langues par page. Sélectionnez les langues pour les textes courts ou peu lisibles.", "Handwriting is experimental using a local printed-text engine, not a specialized handwriting model. Cursive, especially Arabic, may be inaccurate. Review and correct the result. Images stay on your device.": "L’écriture manuscrite est expérimentale avec un moteur local pour texte imprimé, sans modèle spécialisé. L’écriture cursive, surtout arabe, peut être mal reconnue. Vérifiez et corrigez le résultat. Les images restent sur votre appareil.", "No clear text was detected for language identification. Choose the language manually or use a clearer image.": "Aucun texte clair détecté pour identifier la langue. Choisissez la langue ou utilisez une image plus nette."});

Object.assign(catalogs.de,{"Automatically detect language(s)": "Sprache(n) automatisch erkennen", "Text type": "Textart", "Printed text": "Gedruckter Text", "Handwriting — experimental": "Handschrift — experimentell", "Printed and handwritten — experimental": "Druck und Handschrift — experimentell", "Languages used: {languages}": "Verwendete Sprachen: {languages}", "Estimated detection: review languages and select them manually if needed": "Geschätzte Erkennung: Sprachen prüfen und bei Bedarf manuell auswählen", "Automatic detection is approximate and supports up to three languages per page. Select languages manually for short or unclear text.": "Die automatische Erkennung ist eine Schätzung und unterstützt drei Sprachen pro Seite. Bei kurzem oder unklarem Text die Sprachen manuell auswählen.", "Handwriting is experimental using a local printed-text engine, not a specialized handwriting model. Cursive, especially Arabic, may be inaccurate. Review and correct the result. Images stay on your device.": "Handschrift ist experimentell und verwendet eine lokale Drucktexterkennung, kein spezialisiertes Handschriftmodell. Schreibschrift, insbesondere Arabisch, kann ungenau sein. Ergebnis prüfen und korrigieren. Bilder bleiben auf dem Gerät.", "No clear text was detected for language identification. Choose the language manually or use a clearer image.": "Kein klarer Text für die Spracherkennung gefunden. Sprache manuell auswählen oder ein klareres Bild verwenden."});

Object.assign(catalogs.es,{"Automatically detect language(s)": "Detectar idiomas automáticamente", "Text type": "Tipo de texto", "Printed text": "Texto impreso", "Handwriting — experimental": "Escritura a mano — experimental", "Printed and handwritten — experimental": "Impreso y manuscrito — experimental", "Languages used: {languages}": "Idiomas usados: {languages}", "Estimated detection: review languages and select them manually if needed": "Detección aproximada: revisa los idiomas y selecciónalos si es necesario", "Automatic detection is approximate and supports up to three languages per page. Select languages manually for short or unclear text.": "La detección automática es aproximada y admite hasta tres idiomas por página. Selecciona los idiomas para textos cortos o poco claros.", "Handwriting is experimental using a local printed-text engine, not a specialized handwriting model. Cursive, especially Arabic, may be inaccurate. Review and correct the result. Images stay on your device.": "La escritura a mano es experimental con un motor local de texto impreso, sin un modelo especializado. La cursiva, especialmente árabe, puede ser imprecisa. Revisa y corrige el resultado. Las imágenes permanecen en tu dispositivo.", "No clear text was detected for language identification. Choose the language manually or use a clearer image.": "No se detectó texto claro para identificar el idioma. Selecciona el idioma o usa una imagen más nítida."});

Object.assign(catalogs.tr,{"Automatically detect language(s)": "Dilleri otomatik algıla", "Text type": "Metin türü", "Printed text": "Basılı metin", "Handwriting — experimental": "El yazısı — deneysel", "Printed and handwritten — experimental": "Basılı ve el yazısı — deneysel", "Languages used: {languages}": "Kullanılan diller: {languages}", "Estimated detection: review languages and select them manually if needed": "Tahmini algılama: dilleri kontrol edin ve gerekirse elle seçin", "Automatic detection is approximate and supports up to three languages per page. Select languages manually for short or unclear text.": "Otomatik algılama tahminidir ve sayfa başına üç dili destekler. Kısa veya belirsiz metinler için dilleri elle seçin.", "Handwriting is experimental using a local printed-text engine, not a specialized handwriting model. Cursive, especially Arabic, may be inaccurate. Review and correct the result. Images stay on your device.": "El yazısı, özel bir el yazısı modeli yerine yerel basılı metin motoruyla deneyseldir. Bitişik yazı, özellikle Arapça, yanlış okunabilir. Sonucu kontrol edip düzeltin. Görseller cihazınızda kalır.", "No clear text was detected for language identification. Choose the language manually or use a clearer image.": "Dil algılama için net metin bulunamadı. Dili elle seçin veya daha net bir görsel kullanın."});
